func kthSmallest(root *TreeNode, k int) int {
    var res int
    var inorder func(*TreeNode)
    inorder = func(node *TreeNode) {
        if node == nil || k == 0 {
            return
        }
        inorder(node.Left)
        k--
        if k == 0 {
            res = node.Val
            return
        }
        inorder(node.Right)
    }
    inorder(root)
    return res
}

func kthSmallest(root *TreeNode, k int) int {
    stack := []*TreeNode{}
    cur := root
    for cur != nil || len(stack) > 0 {
        for cur != nil {
            stack = append(stack, cur)
            cur = cur.Left
        }
        cur = stack[len(stack)-1]
        stack = stack[:len(stack)-1]
        k--
        if k == 0 {
            return cur.Val
        }
        cur = cur.Right
    }
    return -1
}
